     8→export function ThemeToggle() {
     9→  const { setTheme, theme } = useTheme();
    10→  const [mounted, setMounted] = useState(false);
    11→
    12→  // Prevent hydration mismatch by only rendering after mount
    13→  useEffect(() => {
    14→    setMounted(true);
    15→  }, []);
    16→
    17→  if (!mounted) {
    18→    // Return a placeholder with the same dimensions to avoid layout shift
    19→    return (
    20→      <Button variant="ghost" size="sm" disabled>
    21→        <div className="size-5" />
    22→        <span className="sr-only">Toggle theme</span>
    23→      </Button>
    24→    );
    25→  }
    26→
    27→  return (
    28→    <Button
    29→      variant="ghost"
    30→      size="sm"
    31→      onClick={() => setTheme(theme === "light" ? "dark" : "light")}
    32→    >
    33→      <Sun className="h-6 w-[1.3rem] dark:hidden" />
    34→      <Moon className="hidden size-5 dark:block" />
    35→      <span className="sr-only">Toggle theme</span>
    36→    </Button>
    37→  );
    38→}
