   458→  }
   459→
   460→  /* Grain texture overlay */
   461→  .grain-overlay {
   462→    position: relative;
   463→  }
   464→
   465→  .grain-overlay::before {
   466→    content: "";
   467→    position: absolute;
   468→    inset: 0;
   469→    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
   470→    opacity: 0.04;
   471→    pointer-events: none;
